/* Enhanced invoice deposit for administrators. Keeps existing IndexedDB storage and client linking. */
rc12OpenExternalInvoiceImport=function(){const p=rc11AdminProfile?.();if(typeof rc12AdminPerms==='function'&&!rc12AdminPerms(p).manageExternalInvoices)return toast('No permission.');const clients=typeof rc11VisibleClients==='function'?rc11VisibleClients():[];showModal(`<div class="rc11-modal-wide"><span class="eyebrow">INVOICE DEPOSIT</span><h2>${rc24T('Upload / deposit an accounting invoice','Déposer une facture comptable','Subir / depositar una factura contable')}</h2><p>${rc24T('Attach a PDF/XML invoice generated by EBP, an approved e-invoicing platform or another accounting tool. The file is linked to the selected professional account.','Joignez une facture PDF/XML générée par EBP, une plateforme de facturation électronique agréée ou un autre logiciel comptable. Le fichier est rattaché au compte professionnel sélectionné.','Adjunte una factura PDF/XML generada por EBP, una plataforma autorizada u otro software contable. El archivo se vincula a la cuenta profesional seleccionada.')}</p><div class="rc24-connection-form"><div class="field"><label>${rc24T('Client / professional','Client / professionnel','Cliente / profesional')}</label><select id="rc12ExtClient">${clients.map(c=>`<option value="${c.id}">${rc24Esc(c.company)} — ${rc24Esc(rc11Territory?.(c.territoryId)?.name||'')}</option>`).join('')}</select></div><div class="field"><label>${rc24T('Source','Source','Origen')}</label><select id="rc12ExtSource"><option>EBP</option><option>${rc24T('Approved e-invoicing platform','Plateforme agréée','Plataforma autorizada')}</option><option>Factur-X / XML</option><option>${rc24T('Other accounting software','Autre logiciel comptable','Otro software contable')}</option></select></div><div class="field"><label>${rc24T('Invoice number','N° de facture','N.º factura')}</label><input id="rc12ExtNo"></div><div class="field"><label>${rc24T('Invoice date','Date de facture','Fecha factura')}</label><input id="rc12ExtDate" type="date" value="${new Date().toISOString().slice(0,10)}"></div><div class="field"><label>${rc24T('Due date','Date d’échéance','Fecha vencimiento')}</label><input id="rc24ExtDue" type="date"></div><div class="field"><label>${rc24T('VAT rate (%)','Taux TVA (%)','Tasa IVA (%)')}</label><input id="rc24ExtVatRate" type="number" min="0" step="0.01"></div><div class="field"><label>Total HT</label><input id="rc24ExtHT" type="number" min="0" step=".01"></div><div class="field"><label>TVA</label><input id="rc24ExtVAT" type="number" min="0" step=".01"></div><div class="field"><label>Total TTC</label><input id="rc12ExtAmount" type="number" min="0" step=".01"></div><div class="field"><label>${rc24T('Currency','Devise','Moneda')}</label><select id="rc12ExtCurrency"><option>EUR</option><option>USD</option></select></div><div class="field full"><label>${rc24T('Invoice file','Fichier facture','Archivo factura')}</label><input id="rc12ExtFile" type="file" accept="application/pdf,application/xml,text/xml,.pdf,.xml"></div></div><div class="rc24-security-note" style="margin-top:12px"><span>FR</span><div><b>${rc24T('Archive vs. e-invoicing transmission','Archivage vs transmission électronique','Archivo vs transmisión electrónica')}</b>${rc24T('Depositing a PDF/XML here stores and links the document. When French e-invoicing rules apply, transmission must still follow the approved platform process.','Déposer un PDF/XML ici archive et rattache le document. Lorsque la facturation électronique française s’applique, la transmission doit toujours suivre le circuit de la plateforme agréée.','Subir un PDF/XML aquí archiva y vincula el documento. Cuando se aplique la facturación electrónica francesa, el envío debe seguir el circuito de la plataforma autorizada.')}</div></div><div class="toolbar"><button class="btn secondary" onclick="closeModal()">${rc24T('Cancel','Annuler','Cancelar')}</button><button class="btn primary" id="rc12ExtSave">${rc24T('Deposit invoice','Déposer la facture','Depositar factura')}</button></div></div>`);document.getElementById('rc12ExtSave').onclick=async()=>{const client=store.accounts.find(a=>a.id===document.getElementById('rc12ExtClient').value),file=document.getElementById('rc12ExtFile').files[0],invoiceNumber=document.getElementById('rc12ExtNo').value.trim();if(!client||!file||!invoiceNumber)return toast(rc24T('Client, invoice number and file are required.','Client, numéro de facture et fichier requis.','Cliente, número y archivo obligatorios.'));if(file.size>25*1024*1024)return toast(rc24T('Invoice file exceeds 25 MB.','Le fichier dépasse 25 Mo.','El archivo supera 25 MB.'));const id=rc11SafeId('extinv'),meta={id,clientId:client.id,regionId:client.regionId,territoryId:client.territoryId,source:document.getElementById('rc12ExtSource').value,invoiceNumber,invoiceDate:document.getElementById('rc12ExtDate').value||new Date().toISOString(),dueDate:document.getElementById('rc24ExtDue').value||'',amountHT:Number(document.getElementById('rc24ExtHT').value||0),vatAmount:Number(document.getElementById('rc24ExtVAT').value||0),vatRate:Number(document.getElementById('rc24ExtVatRate').value||0),amount:Number(document.getElementById('rc12ExtAmount').value||0),currency:document.getElementById('rc12ExtCurrency').value,fileName:file.name,fileType:file.type,fileSize:file.size,uploadedAt:new Date().toISOString(),uploadedBy:currentAccount()?.email||''};try{await rc12PutInvoiceFile(id,file);rc12Settings().externalInvoices.unshift(meta);store.tenants[client.id]=store.tenants[client.id]||{};store.tenants[client.id].externalInvoiceIds=store.tenants[client.id].externalInvoiceIds||[];store.tenants[client.id].externalInvoiceIds.push(id);saveStore();closeModal();renderShell();toast(rc24T('Invoice deposited in the client account.','Facture déposée dans le compte client.','Factura depositada en la cuenta del cliente.'))}catch(e){toast(rc24T('Unable to store this file on the device.','Impossible de stocker ce fichier sur cet appareil.','No se pudo guardar el archivo.'))}}}
function rc24EnhanceInvoicesPage(){if(currentView!=='invoices')return;const content=document.getElementById('content');if(!content)return;let panel=document.getElementById('rc24FrancePanel');if(!panel){const host=content.querySelector('.rc11-page-hero,.rc-v10-hero,.hero');if(host)host.insertAdjacentHTML('afterend',rc24InvoiceCompliancePanel());else content.insertAdjacentHTML('afterbegin',rc24InvoiceCompliancePanel())}document.getElementById('rc24ConfigureInvoice')?.addEventListener('click',rc24OpenInvoiceProfile);document.getElementById('rc24UploadInvoice')?.addEventListener('click',rc12OpenExternalInvoiceImport);const old=document.getElementById('rc12ImportExternalInvoice');if(old){old.textContent=rc24T('Upload / deposit external invoice','Déposer une facture externe','Subir factura externa')}}

/* Settings: append Connected Apps without changing left navigation. */
