const rc24RenderContentBase=renderContent;renderContent=function(){const out=rc24RenderContentBase.apply(this,arguments);setTimeout(()=>{try{rc24EnhanceAdminSettings();rc24EnhanceInvoicesPage()}catch(e){console.warn('V24 enhancement',e)}},30);return out};
const rc24OpenInvoiceBase=rc11OpenInvoice;rc11OpenInvoice=function(number){const out=rc24OpenInvoiceBase(number);setTimeout(()=>rc24EnhanceOpenInvoice(number),140);return out};
